/** static void Cmd_count_usable_party_mons(void) */
export function Cmd_count_usable_party_mons(): any {
  let battler: any = null;
      let battlerOnField1, battlerOnField2;
      let party: any = null;
      let i: any = null;

      AI_THINKING_STRUCT.funcResult = 0;

      if (gAIScriptPtr[1] == AI_USER)
          battler = sBattler_AI;
      else
          battler = gBattlerTarget;

      if (GetBattlerSide(battler) == B_SIDE_PLAYER)
          party = gPlayerParty;
      else
          party = gEnemyParty;

      if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE)
      {
          let position: any = null;
          battlerOnField1 = gBattlerPartyIndexes[battler];
          position = BATTLE_PARTNER(GetBattlerPosition(battler));
          battlerOnField2 = gBattlerPartyIndexes[GetBattlerAtPosition(position)];
      }
      else  
      {
          battlerOnField1 = gBattlerPartyIndexes[battler];
          battlerOnField2 = gBattlerPartyIndexes[battler];
      }

      for (i = 0; i < PARTY_SIZE; i++)
      {
          if (i != battlerOnField1 && i != battlerOnField2
           && GetMonData(party[i], MON_DATA_HP) != 0
           && GetMonData(party[i], MON_DATA_SPECIES_OR_EGG) != SPECIES_NONE
           && GetMonData(party[i], MON_DATA_SPECIES_OR_EGG) != SPECIES_EGG)
          {
              AI_THINKING_STRUCT.funcResult++;
          }
      }

      gAIScriptPtr += 2;
}

