/** static void Cmd_if_holds_item(void) */
export function Cmd_if_holds_item(): any {
  let battler = BattleAI_GetWantedBattler(gAIScriptPtr[1]);
      let item: any = null;
      let itemLo, itemHi;

      if ((battler & BIT_SIDE) == (sBattler_AI & BIT_SIDE))
          item = gBattleMons[battler].item;
      else
          item = BATTLE_HISTORY.itemEffects[battler];

      itemHi = gAIScriptPtr[2];
      itemLo = gAIScriptPtr[3];
       
       
       
      if (((itemHi << 8) | itemLo) == item)
      if ((itemLo | itemHi) == item)
          gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 4);
      else
          gAIScriptPtr += 8;
}

